#!/usr/bin/env python3
"""All-region 6/7-node transfer MMS, guard semantics, and convergence plots."""
import argparse,hashlib,json,math,os
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('directory',type=Path);a=p.parse_args();d=a.directory;rows=[json.loads(f.read_text()) for f in sorted(d.glob('mms*.stdout')) if f.stat().st_size];manifest=json.loads((d/'manifest.json').read_text());out=dict(scope='Standalone interpolation and independent AD derivative MMS only; no engine/evolution adoption',prototype_not_adopted=True,physics_gate_tested=False,results=rows,all_tests_exit_zero=all(x['exit_code']==0 for x in manifest['runs'].values()),all_constants_exact=all(x['constant_max']==0 for x in rows),maximum_normal_jet_change=max(x['original_pure_normal_jet_difference_max'] for x in rows),maximum_weight_l1=max(x['volume_MLS_max_l1'] for x in rows),maximum_polynomial_reproduction=max(x['volume_MLS_max_poly_reproduction'] for x in rows),all_cells_under50000=all(x['cells']<=50000 for x in rows),condition_semantics={'fixed_ring_Cartesian_P5_MLS56':'Measured infinity condition of triangular QR factor R56; mandatory threshold1e8','physical_ray_Pn_times_angular_chart_P5':'Product of angular QR-R infinity condition and per-line scaled radial Vandermonde infinity condition. Field-independent factor indicator, not measured full tensor-design matrix condition; mandatory threshold1e8. Raw legacy field name volume_MLS_QR_R_condition_infinity contains this indicator.'},polynomial_semantics={'fixed_ring_Cartesian_P5_MLS56':'56 local Cartesian monomials of total degree<=5; affine target-owner-J scaling; fullrank56','physical_ray_Pn_times_angular_chart_P5':'21 query-centered gnomonic angular monomials times radial_nodes physical-radius monomials;126/147 product reproduction, angular rank21 and normal rank6/7; no claim of exact Cartesian-degree5 reproduction'},observed_orders=[],retained_counterexamples=['CoarseN6 angular/field Hessian errors can be worse than original owner interpolation; resolution studies remain necessary.','Ray interpolation alone rejects one-shell7-node case at L1=11.764885 because constant-radius angular sampling crosses Cartesian core. Geometry specialization is fixed by map type, never field values or row failure.'])
for layers in [1,2,7]:
 for radial in [6,7]:
  selected=sorted((x for x in rows if x['layers']==layers and x['subdivisions']==1 and x['radial_nodes']==radial),key=lambda x:x['n'])
  for x,y in zip(selected,selected[1:]):
   pair=dict(layers=layers,radial_nodes=radial,n_from=x['n'],n_to=y['n'],orders={})
   for region in ['all_surface','edge_band','corner_band','exact_patch_seams_and_corners','owner_all_surface','owner_exact_seams','analytic_pullback_all_surface','analytic_pullback_exact_seams']:
    pair['orders'][region]={k:math.log(x[region][k]/y[region][k])/math.log(y['n']/x['n']) for k in ['first_max','second_max','normal_tangent_hessian_max'] if x[region][k]>0 and y[region][k]>0}
   out['observed_orders'].append(pair)
out['analysis_script_sha256']=hashlib.sha256(Path(__file__).read_bytes()).hexdigest();out['raw_manifest_sha256']=hashlib.sha256((d/'manifest.json').read_bytes()).hexdigest();(d/'analysis.json').write_text(json.dumps(out,indent=2)+'\n')
os.environ.setdefault('MPLCONFIGDIR',str(Path.cwd()/'tmp/matplotlib-boundary-transfer'));import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
fig,axes=plt.subplots(3,3,figsize=(12,10));columns=[('all_surface','second_max','All nodes: Hessian max'),('exact_patch_seams_and_corners','second_max','Exact seams/corners: Hessian max'),('exact_patch_seams_and_corners','normal_tangent_hessian_max','Exact seams/corners: mixed max')]
for i,layers in enumerate([1,2,7]):
 for j,(region,metric,title) in enumerate(columns):
  ax=axes[i,j]
  for radial,style in [(6,'o-'),(7,'s--')]:
   selected=sorted((x for x in rows if x['layers']==layers and x['subdivisions']==1 and x['radial_nodes']==radial),key=lambda x:x['n']);ax.loglog([x['n'] for x in selected],[x[region][metric] for x in selected],style,label=f'new, radial{radial}')
  selected=sorted((x for x in rows if x['layers']==layers and x['subdivisions']==1 and x['radial_nodes']==6),key=lambda x:x['n']);old='owner_all_surface' if region=='all_surface' else 'owner_exact_seams';oracle='analytic_pullback_all_surface' if region=='all_surface' else 'analytic_pullback_exact_seams';ax.loglog([x['n'] for x in selected],[x[old][metric] for x in selected],'x:',color='.5',label='owner face');ax.loglog([x['n'] for x in selected],[x[oracle][metric] for x in selected],'+-.',color='black',label='analytic pullback');ax.set_title(f'{layers} shell(s) — {title}',fontsize=9);ax.grid(True,which='both',alpha=.25);ax.set_xlabel('N per block axis');ax.set_ylabel('Maximum absolute derivative error')
axes[0,0].legend(fontsize=7);fig.suptitle('Independent AD transfer MMS; all nodes retained; no evolution or accuracy gate relaxation',fontsize=12);fig.tight_layout();fig.savefig(d/'convergence.png',dpi=160);fig.savefig(d/'convergence.pdf');plt.close(fig)
print(json.dumps({k:v for k,v in out.items() if k not in ['results','observed_orders','condition_semantics','polynomial_semantics','retained_counterexamples']}))
